# Hintergrund: (id, Abschnitt, Stelle, Kontext, Konfidenz, Thema, Text, unsicher, Belege, Quellen, Fachwörter | Mundart)
BACKGROUND = [
 ("BG-MRK-1001", U(1, 1, 15), "MRK.1.1", READERS, "probable", "«Evangelium» in der damaligen Welt",
  "Im Griechischen bezeichnete εὐαγγέλιον die gute Nachricht und den Botenlohn dafür, etwa die Meldung eines Sieges. In der Verehrung des Kaisers Augustus wurde das Wort für Ereignisse im Herrscherhaus gebraucht: Eine Inschrift aus Priene (9 v. Chr.) sagt, mit dem Geburtstag des «Gottes» Augustus hätten für die Welt die guten Nachrichten begonnen. In der griechischen Bibel verkündet ein Freudenbote, dass Gott König ist und sein Volk befreit ([[ISA.40.9]]; [[ISA.52.7]]; [[ISA.61.1]]). Beide Klangfarben konnten Markus' Leser hören.",
  "Wie weit Markus bewusst auf die Kaisersprache anspielt, ist umstritten (INT-MRK-1001). Die Inschrift ist ein Beispiel unter mehreren; die Form des Wortes ist dort der Plural.",
  ["ISA.40.9", "ISA.52.7", "ISA.61.1", "MRK.1.14-MRK.1.15"], ["Kalenderinschrift von Priene (9 v. Chr.), OGIS 458"],
  [("grc", "εὐαγγέλιον", "gute Nachricht; Botenlohn"), ("heb", "מְבַשֵּׂר", "Freudenbote, Überbringer guter Nachricht", "mᵉbaśśēr")],
  "«Evangelium» i de dameligi Wält",
  "Im Griechische hät εὐαγγέλιον di guet Nachricht und de Botelohn defür bezeichnet, öppe d Meldig vo me Sieg. I de Verehrig vom Kaiser Augustus isch s Wort für Ereignis im Herrscherhuus bruucht worde: E Inschrift us Priene (9 v. Chr.) seit, mit em Geburtstag vom «Gott» Augustus hebed für d Wält di guete Nachrichte aagfange. I de griechische Bible verchündet en Fröidebot, dass Gott König isch und sis Volk befreit ([[ISA.40.9]]; [[ISA.52.7]]; [[ISA.61.1]]). Beidi Klangfarbe händ em Markus sini Läser chöne ghöre.",
  "Wie wiit de Markus bewusst uf d Kaiserspraach aaspilt, isch umstritte (INT-MRK-1001). D Inschrift isch eis Biispil under meerere; s Wort staat dört im Plural.",
  ["gueti Nachricht; Botelohn", "Fröidebot, öpper, wo e gueti Nachricht überbringt"]),
 ("BG-MRK-1002", U(1, 16, 20), "MRK.1.16-MRK.1.20", GAL, "probable", "Fischerei am See Gennesaret",
  "Der See von Galiläa ist rund 21 Kilometer lang und bis etwa 12 Kilometer breit. Fischerei war ein wichtiger Erwerb; in Magdala, griechisch Tarichea («Pökelei»), wurde Fisch eingesalzen und gehandelt. Gefischt wurde mit Wurfnetzen vom Ufer aus, wie Simon und Andreas ([[MRK.1.16]]), und mit grossen Netzen von Booten. 1986 wurde bei Ginosar ein Boot aus dieser Zeit gefunden, rund 8 Meter lang, das nach Schätzungen über ein Dutzend Personen tragen konnte. Zebedäus arbeitete mit Söhnen und Tagelöhnern ([[MRK.1.20]]): ein Familienbetrieb, der auch Fremde beschäftigte. Fischrechte und Abgaben unterstanden den Behörden des Landesfürsten.",
  "Die Masse des Sees schwanken mit dem Wasserstand. Die Datierung des Ginosar-Bootes (etwa 1. Jahrhundert v. bis 1. Jahrhundert n. Chr.) ist eine Spanne; wie die Fischerei im Einzelnen besteuert wurde, ist nur teilweise bekannt.",
  ["MRK.1.16-MRK.1.20", "MRK.4.1", "MRK.4.36-MRK.4.38"], ["Josephus, Jüdischer Krieg 3,506–521", "Strabon, Geographie 16,2,45", "Bootsfund von Ginosar (1986)"],
  [("grc", "ἁλιεύς", "Fischer"), ("grc", "ἀμφιβάλλω", "das Wurfnetz auswerfen"), ("grc", "μισθωτός", "Tagelöhner, Lohnarbeiter")],
  "Fischerei am See Gennesaret",
  "De See vo Galiläa isch öppe 21 Kilometer lang und bis öppe 12 Kilometer breit. D Fischerei isch en wichtige Verdienscht gsii; z Magdala, griechisch Tarichea («Pöklerei»), isch Fisch iigsalze und ghandlet worde. Gfischet hät me mit Wurfnetz vom Ufer uus, wie de Simon und de Andreas ([[MRK.1.16]]), und mit groosse Netz vo Boot uus. 1986 hät me bi Ginosar es Boot us dere Ziit gfunde, öppe 8 Meter lang, wo nach Schätzige meh als es Dotzed Persone hät chöne träge. De Zebedäus hät mit Söön und Taglöönere gschaffet ([[MRK.1.20]]): en Familiebetrieb, wo au Frömdi aagstellt hät. Fischrächt und Abgaabe sind under de Behörde vom Landesfürscht gstande.",
  "D Mass vom See schwanked mit em Wasserstand. D Datierig vom Ginosar-Boot (öppe 1. Jaarhundert v. bis 1. Jaarhundert n. Chr.) isch e Spanne; wie d Fischerei im einzelne bstüüret worde isch, weiss me nu teilwiis.",
  ["Fischer", "s Wurfnetz uswärfe", "Taglööner, Loonarbeiter"]),
 ("BG-MRK-1003", U(1, 21, 28), "MRK.1.21", GAL, "probable", "Kafarnaum und die Synagoge",
  "Kafarnaum war ein Dorf am Nordufer des Sees, nahe der Grenze zwischen dem Gebiet des Herodes Antipas und dem seines Bruders Philippus östlich des Jordan; Josephus erwähnt den Ort. Eine Synagoge («Versammlung») war Ort für Lesung und Auslegung der Tora am Sabbat, aber auch für Gemeindeangelegenheiten. Eine Inschrift aus Jerusalem aus der Zeit vor 70 n. Chr. nennt als Zweck einer Synagoge «das Vorlesen des Gesetzes und das Lehren der Gebote». Aus dem 1. Jahrhundert sind Synagogenbauten etwa in Magdala und Gamla ausgegraben; die erhaltene weisse Synagoge von Kafarnaum stammt aus späterer Zeit und steht auf älteren Basaltmauern. Dass Jesus dort lehrte, setzt voraus, dass auch Gäste das Wort ergreifen konnten ([[MRK.1.21-MRK.1.22]]; vgl. [[LUK.4.16-LUK.4.21]]; [[ACT.13.15]]).",
  "Ob die Basaltmauern unter der späteren Synagoge zur Synagoge aus Jesu Zeit gehören, ist umstritten. In Dörfern konnte die Versammlung auch in Häusern oder unter freiem Himmel stattfinden.",
  ["MRK.1.21-MRK.1.29", "MRK.2.1", "LUK.4.16-LUK.4.21", "ACT.13.15"],
  ["Theodotos-Inschrift (Jerusalem, vor 70 n. Chr.)", "Josephus, Jüdischer Krieg 3,519", "Josephus, Leben (Vita) 403"],
  [("grc", "συναγωγή", "Versammlung; Versammlungshaus"), ("heb", "בֵּית הַכְּנֶסֶת", "Haus der Versammlung, Synagoge", "bêt hakkᵉneset")],
  "Kafarnaum und d Synagoge",
  "Kafarnaum isch es Dorf am Nordufer vom See gsii, nööch a de Gränze zwüsche em Gebiet vom Herodes Antipas und em Gebiet vo sim Brueder Philippus öschtlich vom Jordan; de Josephus erwäänt de Ort. E Synagoge («Versammlig») isch de Ort gsii für s Vorläse und Uuslege vo de Tora am Sabbat, aber au für Gmeindsaagläägeheite. E Inschrift us Jerusalem us de Ziit vor 70 n. Chr. nännt als Zwäck vo ere Synagoge «s Vorläse vom Gsetz und s Leere vo de Gebot». Us em 1. Jaarhundert sind Synagogebaute öppe z Magdala und z Gamla uusgrabe; di erhalte wiiss Synagoge vo Kafarnaum stammt us spööterer Ziit und staat uf eltere Basaltmuure. Dass de Jesus dört gleert hät, setzt voruus, dass au Gäscht händ dörfe s Wort ergriiffe ([[MRK.1.21-MRK.1.22]]; vgl. [[LUK.4.16-LUK.4.21]]; [[ACT.13.15]]).",
  "Öb d Basaltmuure under de spöötere Synagoge zur Synagoge us de Ziit vo Jesus ghöred, isch umstritte. I Dörfer hät d Versammlig au i Hüüser oder unter freiem Himmel chöne stattfinde.",
  ["Versammlig; Versammligshuus", "Huus vo de Versammlig, Synagoge"]),
 ("BG-MRK-1004", U(1, 40, 45), "MRK.1.40-MRK.1.44", GAL, "probable", "Aussatz und Reinheit",
  "Was die Bibel «Aussatz» nennt (hebräisch ṣāraʿat, griechisch λέπρα), umfasste verschiedene Hautkrankheiten und sogar Befall an Kleidern und Häusern; mit der heutigen Lepra ist es nicht gleichzusetzen. Wer davon befallen war, galt als unrein, musste ausserhalb der Siedlung leben und andere warnen ([[LEV.13.45-LEV.13.46]]; [[NUM.5.2]]). Wer ihn berührte, wurde selbst unrein ([[LEV.5.3]]). Heilung stellte nicht ein Arzt fest, sondern ein Priester, und sie war mit Opfern verbunden ([[LEV.14.1-LEV.14.32]]); darum schickt Jesus den Geheilten zum Priester ([[MRK.1.44]]). Heilung von Aussatz galt als Werk Gottes ([[2KI.5.7]]).",
  "Wie streng die Absonderung im Galiläa des 1. Jahrhunderts gehandhabt wurde, ist nicht genau bekannt.",
  ["LEV.13.45-LEV.13.46", "LEV.5.3", "LEV.14.1-LEV.14.32", "NUM.5.2", "2KI.5.7", "MRK.1.40-MRK.1.45"], [],
  [("heb", "צָרַעַת", "«Aussatz»: Hautkrankheit, die unrein macht", "ṣāraʿat"), ("grc", "λέπρα", "Aussatz, schuppige Hautkrankheit"), ("grc", "καθαρίζω", "rein machen")],
  "Uussatz und Reinheit",
  "Was d Bible «Uussatz» nännt (hebräisch ṣāraʿat, griechisch λέπρα), hät verschideni Huutchrankheite umfasst und sogar Befall a Chleider und Hüüser; mit de hütige Lepra isch es nöd gliichzsetze. Wär devo befalle gsii isch, hät als unrein gulte, hät usserhalb vo de Siedlig müese läbe und anderi warne ([[LEV.13.45-LEV.13.46]]; [[NUM.5.2]]). Wär en berüert hät, isch sälber unrein worde ([[LEV.5.3]]). D Heilig hät nöd en Dokter feschtgstellt, sondern en Prieschter, und si isch mit Opfer verbunde gsii ([[LEV.14.1-LEV.14.32]]); drum schickt de Jesus de Gheilt zum Prieschter ([[MRK.1.44]]). Heilig vo Uussatz hät als Wärch vo Gott gulte ([[2KI.5.7]]).",
  "Wie sträng d Absonderig im Galiläa vom 1. Jaarhundert ghandhabt worde isch, weiss me nöd gnau.",
  ["«Uussatz»: Huutchrankheit, wo unrein macht", "Uussatz, schuppigi Huutchrankheit", "rein mache"]),
 ("BG-MRK-1005", U(2, 13, 17), "MRK.2.14-MRK.2.16", GAL, "probable", "Zöllner",
  "Die «Zöllner» (τελῶναι) erhoben Zölle und Abgaben auf Waren an Strassen, Brücken und Grenzen; in Galiläa geschah das im Auftrag des Landesfürsten Herodes Antipas. Kafarnaum lag nahe der Grenze zum Gebiet des Philippus, an einem Weg um den See; eine Zollstelle dort ist gut vorstellbar ([[MRK.2.14]]). Zölle wurden oft an Unternehmer verpachtet, die mehr eintreiben konnten, als sie abführen mussten. Zöllner galten als habgierig und, weil sie mit Nichtjuden und fremden Waren umgingen, als bedenklich in Reinheitsfragen. Die Mischna erlaubt, Zöllnern gegenüber unwahre Gelübde abzulegen, und sagt, ein Haus werde unrein, wenn Zöllner es betreten haben. Die Verbindung «Zöllner und Sünder» ([[MRK.2.15-MRK.2.16]]) spiegelt diesen Ruf.",
  "Die Mischna wurde um 200 n. Chr. niedergeschrieben; wie weit ihre Regeln die Zeit Jesu spiegeln, ist im Einzelfall offen. Wie die Abgaben im Galiläa des Antipas genau organisiert waren, ist nur teilweise bekannt.",
  ["MRK.2.13-MRK.2.17", "LUK.3.12-LUK.3.13", "LUK.19.8"], ["Mischna, Nedarim 3,4", "Mischna, Toharot 7,6"],
  [("grc", "τελώνης", "Zöllner, Zollpächter oder -einnehmer"), ("grc", "τελώνιον", "Zollstelle")],
  "Zöllner",
  "D «Zöllner» (τελῶναι) händ Zöll und Abgaabe uf Ware a Strasse, Brugge und Gränze iizoge; z Galiläa isch das im Uuftrag vom Landesfürscht Herodes Antipas gscheh. Kafarnaum isch nööch a de Gränze zum Gebiet vom Philippus gläge, a me Wäg um de See; e Zollstell dört cha me sich guet vorstelle ([[MRK.2.14]]). Zöll sind oft a Unternäämer verpachtet worde, wo meh händ chöne iitriibe, als si händ müese abliefere. Zöllner händ als giirig gulte und, wil si mit Nöd-Jude und frömde Ware z tue gha händ, als bedänklich i Reinheitsfrage. D Mischna erlaubt, Zöllner gägenüber unwaari Glübd abzlegge, und seit, es Huus wärdi unrein, wänn Zöllner drin gsii sind. D Verbindig «Zöllner und Sünder» ([[MRK.2.15-MRK.2.16]]) spieglet dä Ruef.",
  "D Mischna isch um 200 n. Chr. ufgschribe worde; wie wiit iri Regle d Ziit vo Jesus spiegled, isch im Einzelfall offe. Wie d Abgaabe im Galiläa vom Antipas gnau organisiert gsii sind, weiss me nu teilwiis.",
  ["Zöllner, Zollpächter oder -iinämer", "Zollstell"]),
 ("BG-MRK-1006", U(2, 23, 28), "MRK.2.23-MRK.3.6", GAL, "probable", "Sabbat",
  "Der Sabbat, der siebte Tag, war Ruhetag nach dem Gebot ([[EXO.20.8-EXO.20.11]]), «auch in der Zeit des Pflügens und der Ernte» ([[EXO.34.21]]). Ähren mit der Hand abzurupfen war im Feld eines anderen erlaubt ([[DEU.23.25]]); umstritten war es am Sabbat, weil es als Ernten gelten konnte. Die Mischna zählt später 39 Hauptarbeiten auf, die am Sabbat verboten sind, darunter das Ernten. Wie streng man den Sabbat hielt, war unterschiedlich: Die Damaskusschrift aus Qumran verbietet sogar, einem Tier aus einer Grube zu helfen; nach der Mischna verdrängt dagegen jede Lebensgefahr den Sabbat. In der Makkabäerzeit hatten Juden beschlossen, sich am Sabbat zu verteidigen, nachdem eine Gruppe sich lieber hatte töten lassen. Ein rabbinisches Wort lautet: «Euch ist der Sabbat übergeben, und nicht ihr dem Sabbat» (vgl. [[MRK.2.27]]).",
  "Mischna und Mekhilta sind später als das Neue Testament niedergeschrieben; sie zeigen die Breite der Diskussion, nicht unbedingt die Regeln in Galiläa um 30 n. Chr.",
  ["EXO.20.8-EXO.20.11", "EXO.34.21", "DEU.23.25", "MRK.2.23-MRK.2.28", "MRK.3.1-MRK.3.6"],
  ["Mischna, Schabbat 7,2", "Mischna, Joma 8,6", "Damaskusschrift (CD) 11,13–17", "1. Makkabäer 2,29–41", "Mekhilta zu Exodus 31,13"],
  [("heb", "שַׁבָּת", "Sabbat, Ruhetag", "šabbāt"), ("grc", "σάββατον", "Sabbat")],
  "Sabbat",
  "De Sabbat, de siebt Tag, isch nach em Gebot Ruetag gsii ([[EXO.20.8-EXO.20.11]]), «au i de Ziit vom Pflüege und vo de Ärn» ([[EXO.34.21]]). Äere mit de Hand abzrupfe isch im Fäld vo me andere erlaubt gsii ([[DEU.23.25]]); umstritte isch es am Sabbat gsii, wil s als Ärne hät chöne gälte. D Mischna zellt spööter 39 Hauptarbete uf, wo am Sabbat verbote sind, under anderem s Ärne. Wie sträng me de Sabbat ghalte hät, isch verschide gsii: D Damaskusschrift us Qumran verbüütet sogar, eme Tier us ere Gruebe z hälfe; nach de Mischna verdrängt dergäge jedi Läbesgfaar de Sabbat. I de Makkabäerziit händ Jude beschlosse, sich am Sabbat z verteidige, nachdem sich e Gruppe lieber hät loo töte. Es rabbinischs Wort heisst: «Eu isch de Sabbat übergää, und nöd ir em Sabbat» (vgl. [[MRK.2.27]]).",
  "Mischna und Mekhilta sind spööter als s Nöi Teschtamänt ufgschribe worde; si zeiged d Breiti vo de Diskussion, nöd unbedingt d Regle z Galiläa um 30 n. Chr.",
  ["Sabbat, Ruetag", "Sabbat"]),
 ("BG-MRK-1007", U(3, 1, 6), "MRK.3.6", GAL, "possible", "Pharisäer und Herodianer",
  "Die Pharisäer waren eine Bewegung frommer Laien und Schriftkundiger, die das Gesetz im Alltag genau halten wollten, auch mit Reinheitsregeln, die sonst für Priester galten. Nach Josephus gaben sie dem Volk Bestimmungen «aus der Überlieferung der Väter» weiter, die nicht im Gesetz Moses aufgeschrieben waren (vgl. [[MRK.7.3]]; [[MRK.7.5]]). Die «Herodianer» werden im Neuen Testament nur in [[MRK.3.6]], [[MRK.12.13]] und [[MAT.22.16]] genannt; gemeint sind wohl Anhänger oder Gefolgsleute der Herodesfamilie, in Galiläa des Antipas. Dass Pharisäer und Herodianer gemeinsam beraten, verbindet religiöse Kritik mit der Macht des Landesfürsten, der später Johannes den Täufer hinrichten liess ([[MRK.6.14-MRK.6.29]]).",
  "Wer die Herodianer genau waren, ist unbekannt; ausserhalb des Neuen Testaments ist die Bezeichnung in dieser Form nicht sicher belegt. Wie stark die Pharisäer zur Zeit Jesu in Galiläa vertreten waren, ist umstritten.",
  ["MRK.3.6", "MRK.12.13", "MAT.22.16", "MRK.7.3-MRK.7.5", "MRK.8.15"], ["Josephus, Jüdische Altertümer 13,297"],
  [("grc", "Ἡρῳδιανοί", "Herodianer"), ("heb", "פְּרוּשִׁים", "Pharisäer, wörtlich wohl «Abgesonderte»", "pᵉrûšîm")],
  "Pharisäer und Herodianer",
  "D Pharisäer sind e Bewegig vo fromme Laie und Schriftkundige gsii, wo s Gsetz im Alltag gnau händ wele halte, au mit Reinheitsregle, wo süscht für Prieschter gulte händ. Nach em Josephus händ si em Volk Bestimmige «us de Überliferig vo de Vätter» wiitergää, wo nöd im Gsetz vom Mose ufgschribe gsii sind (vgl. [[MRK.7.3]]; [[MRK.7.5]]). D «Herodianer» wärded im Nöie Teschtamänt nu i [[MRK.3.6]], [[MRK.12.13]] und [[MAT.22.16]] gnännt; gmeint sind wahrschiinli Aahänger oder Gfolgslüüt vo de Herodesfamilie, z Galiläa vom Antipas. Dass Pharisäer und Herodianer zäme beraated, verbindet religiösi Kritik mit de Macht vom Landesfürscht, wo spööter de Johannes de Täufer hät loo hiirichte ([[MRK.6.14-MRK.6.29]]).",
  "Wär d Herodianer gnau gsii sind, weiss me nöd; usserhalb vom Nöie Teschtamänt isch d Bezeichnig i dere Form nöd sicher belegt. Wie stark d Pharisäer zur Ziit vo Jesus z Galiläa vertrette gsii sind, isch umstritte.",
  ["Herodianer", "Pharisäer, wörtlich wahrschiinli «Abgsonderti»"]),
 ("BG-MRK-1008", U(5, 1, 20), "MRK.5.1", GAL, "probable", "Dekapolis und Gerasa",
  "Die Dekapolis («Zehn Städte») war eine Gruppe griechisch geprägter Städte, meist östlich des Jordan; Plinius der Ältere zählt unter anderen Skythopolis, Gadara, Hippos, Pella und Gerasa (bei ihm «Galasa») dazu. Dort lebten überwiegend Nichtjuden; Schweinezucht, für Juden unrein ([[LEV.11.7]]), passt in diese Umgebung. Gerasa (heute Jerash in Jordanien) liegt rund 50–60 Kilometer südöstlich des Sees, Gadara etwa 10 Kilometer. Am Ostufer, bei Kursi, wurde in byzantinischer Zeit eine Kirche mit Kloster gebaut, wo man den Ort des Wunders sah. Eine römische Legion umfasste mehrere tausend Soldaten; im 1. Jahrhundert waren Legionen in Syrien stationiert.",
  "Die Liste der zehn Städte schwankte in den Quellen. Welcher Ort ursprünglich gemeint war, ist offen (QUESTION-MRK-1005). Die Stärke einer Legion wird meist mit etwa 5000 bis 6000 Mann angegeben.",
  ["MRK.5.1", "MRK.5.11-MRK.5.13", "MRK.5.20", "MRK.7.31", "LEV.11.7", "MAT.8.28", "LUK.8.26"], ["Plinius der Ältere, Naturalis historia 5,74"],
  [("grc", "Δεκάπολις", "Zehnstädtegebiet"), ("grc", "λεγιών", "Legion")],
  "Dekapolis und Gerasa",
  "D Dekapolis («Zää Stedt») isch e Gruppe vo griechisch prägte Stedt gsii, meischtens öschtlich vom Jordan; de Plinius de Elter zellt under anderem Skythopolis, Gadara, Hippos, Pella und Gerasa (bi ihm «Galasa») dezue. Dört händ vor allem Nöd-Jude gläbt; Söizucht, für Jude unrein ([[LEV.11.7]]), passt i die Umgäbig. Gerasa (hüt Jerash z Jordanie) liit öppe 50–60 Kilometer südöstlich vom See, Gadara öppe 10 Kilometer. Am Oschtufer, bi Kursi, isch i de byzantinische Ziit e Chile mit Chloschter baut worde, wo me de Ort vom Wunder gseh hät. E römischi Legion hät meereri tuusig Soldate umfasst; im 1. Jaarhundert sind Legione z Syrie stationiert gsii.",
  "D Lischte vo de zää Stedt hät i de Quälle gschwankt. Weli Ort ursprünglich gmeint gsii isch, isch offe (QUESTION-MRK-1005). D Stärchi vo ere Legion wird meischtens mit öppe 5000 bis 6000 Maa aaggää.",
  ["Zäästedtgebiet", "Legion"]),
 ("BG-MRK-1009", U(6, 14, 29), "MRK.6.14-MRK.6.29", GAL, "probable", "Herodes Antipas, Herodias und der Tod des Täufers",
  "Herodes Antipas, ein Sohn Herodes' des Grossen, regierte von 4 v. Chr. bis 39 n. Chr. Galiläa und Peräa als Tetrarch («Vierfürst»); König war er nie, Markus gebraucht den volkstümlichen Titel ([[MRK.6.14]]; vgl. [[MAT.14.1]]; [[LUK.3.19]]). Er heiratete Herodias, die Frau eines Halbbruders, und verstiess dafür seine erste Frau, eine Tochter des Nabatäerkönigs Aretas; Aretas besiegte ihn später. Josephus berichtet, Antipas habe Johannes in der Festung Machärus östlich des Toten Meeres hinrichten lassen, weil er fürchtete, dessen Einfluss auf das Volk könne zu einem Aufruhr führen; viele hätten die Niederlage gegen Aretas als Strafe Gottes für diesen Mord gesehen. Nach Josephus hiess der erste Mann der Herodias Herodes; ihre Tochter Salome heiratete den Tetrarchen Philippus. Im Jahr 39 wurde Antipas von Kaiser Caligula abgesetzt und verbannt.",
  "Markus und Josephus nennen verschiedene Gründe (Kritik an der Ehe bzw. Furcht vor Aufruhr); beides kann zusammen gelten. Der Name des Mädchens steht nicht bei Markus. Zur Namensfrage siehe QUESTION-MRK-1001.",
  ["MRK.6.14-MRK.6.29", "MAT.14.1-MAT.14.12", "LUK.3.19-LUK.3.20", "LEV.18.16", "LEV.20.21"],
  ["Josephus, Jüdische Altertümer 18,109–119", "Josephus, Jüdische Altertümer 18,136–137", "Josephus, Jüdische Altertümer 18,240–256"],
  [("grc", "τετραάρχης", "Tetrarch, Vierfürst: abhängiger Teilherrscher"), ("grc", "βασιλεύς", "König")],
  "Herodes Antipas, d Herodias und de Tod vom Täufer",
  "De Herodes Antipas, en Sohn vom Herodes em Groosse, hät vo 4 v. Chr. bis 39 n. Chr. Galiläa und Peräa als Tetrarch («Vierfürscht») regiert; König isch er nie gsii, de Markus bruucht de volkstümlich Titel ([[MRK.6.14]]; vgl. [[MAT.14.1]]; [[LUK.3.19]]). Er hät d Herodias ghürate, d Frau vo me Halbbrueder, und hät defür sini erscht Frau verstosse, e Tochter vom Nabatäerkönig Aretas; de Aretas hät en spööter bsiegt. De Josephus bricht, de Antipas heg de Johannes i de Feschtig Machärus öschtlich vom Tote Meer loo hiirichte, wil er gförchtet heg, dass sin Iifluss uf s Volk zu me Uufruer chönt füere; vili hebed d Niderlag gäge de Aretas als Straf vo Gott für dä Mord aagluegt. Nach em Josephus hät de erscht Maa vo de Herodias Herodes gheisse; iri Tochter Salome hät de Tetrarch Philippus ghürate. Im Jaar 39 isch de Antipas vom Kaiser Caligula abgsetzt und verbannt worde.",
  "De Markus und de Josephus nänned verschideni Gründ (Kritik a de Ee bzw. Angscht vor Uufruer); beides cha zäme gälte. De Name vom Meitli staat nöd bim Markus. Zur Namesfrag lueg QUESTION-MRK-1001.",
  ["Tetrarch, Vierfürscht: abhängige Teilherrscher", "König"]),
 ("BG-MRK-1010", U(7, 1, 23), "MRK.7.3-MRK.7.11", GAL, "probable", "Händewaschen und Korban",
  "Das Gesetz schrieb Waschungen vor allem für Priester vor ([[EXO.30.17-EXO.30.21]]). Pharisäische Kreise übertrugen Reinheitsregeln auf das Essen im Alltag; später widmete die Mischna dem Händewaschen einen eigenen Traktat (Jadajim). Markus erklärt diese Bräuche seinen Lesern und verallgemeinert dabei («alle Juden», [[MRK.7.3]]). «Korban» (hebräisch qorbān, «Darbringung») war eine Weiheformel: Was so bezeichnet wurde, galt als Gott geweiht und durfte von anderen nicht genutzt werden. Ein Ossuar (Knochenkasten) aus der Nähe von Jerusalem trägt eine aramäische Inschrift mit diesem Wort, die alles, was jemand aus diesem Kasten an Nutzen ziehen könnte, zum «Korban», zur Gott geweihten Gabe, erklärt. Die Mischna behandelt solche Gelübde im Traktat Nedarim und kennt auch Wege, sie zugunsten der Eltern aufzulösen.",
  "Wie verbreitet die pharisäischen Reinheitsbräuche zur Zeit Jesu waren, ist umstritten. Die rabbinische Diskussion über das Auflösen von Gelübden ist später niedergeschrieben als Markus.",
  ["EXO.30.17-EXO.30.21", "MRK.7.1-MRK.7.13", "LEV.27.1-LEV.27.34", "NUM.30.2"],
  ["Mischna, Traktat Jadajim", "Mischna, Traktat Nedarim", "Joseph A. Fitzmyer, «The Aramaic Qorbān Inscription from Jebel Hallet eṭ-Ṭûri and Mark 7:11/Matt 15:5», Journal of Biblical Literature 78 (1959)"],
  [("heb", "קָרְבָּן", "Darbringung, Opfergabe; Weiheformel bei Gelübden", "qorbān"), ("grc", "κορβᾶν", "Korban (griechische Umschrift)"), ("grc", "πυγμή", "Faust; Bedeutung beim Händewaschen unsicher")],
  "Händwäsche und Korban",
  "S Gsetz hät Wäschige vor allem für Prieschter vorgschribe ([[EXO.30.17-EXO.30.21]]). Pharisäischi Chreis händ Reinheitsregle uf s Ässe im Alltag übertreit; spööter hät d Mischna em Händwäsche en eigete Traktat gwidmet (Jadajim). De Markus erklärt die Brüüch sine Läser und verallgemeineret debii («alli Jude», [[MRK.7.3]]). «Korban» (hebräisch qorbān, «Darbringig») isch e Wiiheformle gsii: Was eso bezeichnet worde isch, hät als Gott gwiiht gulte und hät vo andere nöd dörfe bruucht wärde. Es Ossuar (Chnochechäschtli) us de Nööchi vo Jerusalem treit e aramäischi Inschrift mit dem Wort, wo alles, was öpper us dem Chäschtli chönt für sich nutze, zum «Korban», zur Gott gwiihte Gaab, erklärt. D Mischna behandlet settigi Glübd im Traktat Nedarim und kännt au Wäg, si zgunschte vo de Eltere ufzlöse.",
  "Wie verbreitet di pharisäische Reinheitsbrüüch zur Ziit vo Jesus gsii sind, isch umstritte. Di rabbinisch Diskussion über s Uflöse vo Glübd isch spööter ufgschribe worde als de Markus.",
  ["Darbringig, Opfergaab; Wiiheformle bi Glübd", "Korban (griechischi Umschrift)", "Fuuscht; Bedüütig bim Händwäsche unsicher"]),
 ("BG-MRK-1011", U(7, 24, 30), "MRK.7.24-MRK.7.31", GAL, "possible", "Tyros, Sidon und die Syrophönizierin",
  "Tyros und Sidon waren reiche phönizische Handelsstädte an der Küste nordwestlich von Galiläa. Ihr Hinterland reichte bis an galiläische Dörfer, und sie bezogen Getreide aus dem Land Israel (vgl. [[1KI.5.11]]; [[ACT.12.20]]). Josephus nennt die Tyrer den Juden besonders feindlich gesinnt; beim Ausbruch des Krieges 66 n. Chr. wurden in Tyros viele Juden getötet oder gefangen gesetzt. «Syrophönizierin» bezeichnet eine Phönizierin aus der Provinz Syrien, im Unterschied zu den Phöniziern um Karthago; «Griechin» meint hier eine Nichtjüdin griechischer Sprache und Kultur. Gerd Theissen hat vorgeschlagen, das Wort vom Brot der Kinder ([[MRK.7.27]]) vor dem Hintergrund dieser Spannungen zu lesen: Die Städter lebten auf Kosten der jüdischen Landbevölkerung.",
  "Theissens Deutung ist eine Rekonstruktion; die Spannungen sind belegt, ihr Bezug auf die Erzählung ist erschlossen. Ob Markus die Region aus eigener Kenntnis beschreibt, ist umstritten; der Weg «über Sidon» an den See ([[MRK.7.31]]) ist ein grosser Umweg.",
  ["MRK.3.8", "MRK.7.24-MRK.7.31", "1KI.5.11", "ACT.12.20"],
  ["Josephus, Gegen Apion 1,70", "Josephus, Jüdischer Krieg 2,478", "Gerd Theissen, Lokalkolorit und Zeitgeschichte in den Evangelien (1989)"],
  [("grc", "Συροφοινίκισσα", "Syrophönizierin"), ("grc", "Ἑλληνίς", "Griechin; Nichtjüdin")],
  "Tyros, Sidon und d Syrophönizierin",
  "Tyros und Sidon sind riichi phönizischi Handelsstedt a de Chüschte nordweschtlich vo Galiläa gsii. Ires Hinderland isch bis a galiläischi Dörfer gange, und si händ Getreide us em Land Israel bezoge (vgl. [[1KI.5.11]]; [[ACT.12.20]]). De Josephus nännt d Tyrer de Jude bsunders feindlich gsinnt; bim Uusbruch vom Chrieg 66 n. Chr. sind z Tyros vili Jude tötet oder gfange gnoo worde. «Syrophönizierin» bezeichnet e Phönizierin us de Provinz Syrie, im Underschid zu de Phönizier um Karthago; «Griechin» meint da e Nöd-Jüdin vo griechischer Spraach und Kultur. De Gerd Theissen hät vorgschlage, s Wort vom Broot vo de Chind ([[MRK.7.27]]) vor em Hindergrund vo dene Spannige z läse: D Stadtlüüt hebed uf Choschte vo de jüdische Landbevölkerig gläbt.",
  "Em Theissen sini Düütig isch e Rekonstruktion; d Spannige sind belegt, ire Bezug uf d Gschicht isch erschlosse. Öb de Markus d Region us eigeter Kenntnis beschriibt, isch umstritte; de Wäg «über Sidon» an See ([[MRK.7.31]]) isch en groosse Umwäg.",
  ["Syrophönizierin", "Griechin; Nöd-Jüdin"]),
 ("BG-MRK-1012", U(8, 27, 30), "MRK.8.27", GAL, "probable", "Cäsarea Philippi",
  "Cäsarea Philippi lag an einer der Quellen des Jordan am Fuss des Hermon, rund 40 Kilometer nördlich des Sees. Der Ort hiess Paneas nach einer Grotte, in der der griechische Hirtengott Pan verehrt wurde. Herodes der Grosse liess dort einen Tempel für Kaiser Augustus bauen. Sein Sohn Philippus, Tetrarch des Gebiets, baute die Stadt aus und nannte sie zu Ehren des Kaisers Caesarea; zur Unterscheidung von Caesarea am Meer hiess sie «Caesarea des Philippus». Jesus fragt nach seiner Identität also in einer Gegend mit nichtjüdischen Heiligtümern und Kaiserkult.",
  "Ob Markus die Umgebung bewusst als Kontrast zum Bekenntnis einsetzt, ist Deutung; er nennt nur «die Dörfer von Cäsarea Philippi».",
  ["MRK.8.27", "MAT.16.13"],
  ["Josephus, Jüdische Altertümer 15,363–364", "Josephus, Jüdische Altertümer 18,28", "Josephus, Jüdischer Krieg 1,404–406"],
  [("grc", "Καισάρεια ἡ Φιλίππου", "Cäsarea des Philippus")],
  "Cäsarea Philippi",
  "Cäsarea Philippi isch a eine vo de Quälle vom Jordan am Fuess vom Hermon gläge, öppe 40 Kilometer nördlich vom See. De Ort hät Paneas gheisse, nach ere Grotte, wo de griechisch Hirtegott Pan verehrt worde isch. De Herodes de Groos hät dört en Tämpel für de Kaiser Augustus loo baue. Sin Sohn Philippus, de Tetrarch vom Gebiet, hät d Stadt uusbaut und si em Kaiser zu Eere Caesarea gnännt; zur Underscheidig vo Caesarea am Meer hät si «Caesarea vom Philippus» gheisse. De Jesus fröget also i ere Gäged mit nöd-jüdische Heiligtüümer und Kaiserkult, wär er isch.",
  "Öb de Markus d Umgäbig bewusst als Kontrascht zum Bekänntnis iisetzt, isch Düütig; er nännt nu «d Dörfer vo Cäsarea Philippi».",
  ["Cäsarea vom Philippus"]),
 ("BG-MRK-1013", U(5, 35, 43), "MRK.5.41", READERS, "probable", "Aramäische Worte bei Markus",
  "Jesus und seine Jünger sprachen im Alltag Aramäisch (BG-MRK-0001). Markus schreibt griechisch, gibt aber einige Worte in aramäischer (bei «Korban» hebräisch-aramäischer) Form wieder und übersetzt sie: «Talita kum», «Mädchen, steh auf» ([[MRK.5.41]]); «Effata», «Öffne dich» ([[MRK.7.34]]); dazu Boanerges ([[MRK.3.17]]), Korban ([[MRK.7.11]]; BG-MRK-1010) und später «Abba» und der Ruf am Kreuz ([[MRK.14.36]]; [[MRK.15.34]]). Die Übersetzungen zeigen, dass seine Leser kein Aramäisch verstanden. Dass gerade bei Heilungsworten der fremde Wortlaut erhalten blieb, ist auffällig; in der Umwelt galten fremdsprachige Worte oft als besonders wirksam.",
  "Die genaue aramäische Form von «Effata» ist unsicher (ʾeppətaḥ aus ʾetpətaḥ, oder eine hebräische Form); auch bei «Talita kum» überliefern die Handschriften verschiedene Formen (κουμ, κοῦμι). Ob Markus die Worte als Heilformeln verstanden wissen wollte, ist Deutung; er nennt sie nur und übersetzt sie.",
  ["MRK.3.17", "MRK.5.41", "MRK.7.11", "MRK.7.34", "MRK.14.36", "MRK.15.34"], [],
  [("arc", "טַלְיְתָא קוּם", "Mädchen, steh auf (aramäisch; Schreibung rekonstruiert)", "ṭalyᵉtāʾ qûm"),
   ("arc", "אֶתְפְּתַח", "öffne dich (aramäisch; Form rekonstruiert)", "ʾetpᵉtaḥ"),
   ("grc", "Ταλιθα κουμ", "Talita kum (griechische Umschrift)"), ("grc", "Εφφαθα", "Effata (griechische Umschrift)")],
  "Aramäischi Wort bim Markus",
  "De Jesus und sini Jünger händ im Alltag Aramäisch gredt (BG-MRK-0001). De Markus schriibt griechisch, git aber es paar Wort i aramäischer (bi «Korban» hebräisch-aramäischer) Form wider und übersetzt si: «Talita kum», «Meitli, stand uf» ([[MRK.5.41]]); «Effata», «Gang uf» ([[MRK.7.34]]); dezue Boanerges ([[MRK.3.17]]), Korban ([[MRK.7.11]]; BG-MRK-1010) und spööter «Abba» und de Ruef am Chrüüz ([[MRK.14.36]]; [[MRK.15.34]]). D Übersetzige zeiged, dass sini Läser kei Aramäisch verstande händ. Dass grad bi Heiligswort de frömd Wortluut erhalte blibe isch, isch uffällig; i de Umwält händ frömdspraachigi Wort oft als bsunders würksam gulte.",
  "Di gnau aramäisch Form vo «Effata» isch unsicher (ʾeppətaḥ us ʾetpətaḥ, oder e hebräischi Form); au bi «Talita kum» überliefered d Handschrifte verschideni Forme (κουμ, κοῦμι). Öb de Markus d Wort als Heilformle verstande ha wott, isch Düütig; er nännt si nu und übersetzt si.",
  ["Meitli, stand uf (aramäisch; Schriibig rekonstruiert)", "gang uf, öffne dich (aramäisch; Form rekonstruiert)", "Talita kum (griechischi Umschrift)", "Effata (griechischi Umschrift)"]),
]

SUMMARIES = [
 ("SUM-CH-MRK-001", "Markus beginnt mit dem «Anfang des Evangeliums»: Johannes tauft in der Wüste, Jesus wird getauft und vom Geist in die Wüste getrieben. In Galiläa verkündet er das nahe Reich Gottes, beruft Fischer, lehrt mit Vollmacht in Kafarnaum, treibt Geister aus, heilt viele und reinigt einen Aussätzigen, der trotz Schweigegebot alles weitererzählt.",
  "De Markus fangt mit em «Aafang vom Evangelium» aa: De Johannes tauft i de Wüeschti, de Jesus wird tauft und vom Geischt i d Wüeschti triibe. Z Galiläa verchündet er s nööch Riich vo Gott, rüeft Fischer, leert mit Vollmacht z Kafarnaum, triibt Geischter uus, heilt vili und macht en Uussätzige rein, wo trotz Schwiigebot alles wiiterverzellt."),
 ("SUM-CH-MRK-002", "Jesus vergibt einem Gelähmten die Sünden und heilt ihn, beruft den Zöllner Levi und isst mit Zöllnern und Sündern. In Streitgesprächen über Vergebung, Tischgemeinschaft, Fasten und das Ährenrupfen am Sabbat antwortet er seinen Kritikern: Der Sabbat ist für den Menschen da.",
  "De Jesus vergit eme Glähmte d Sünde und heilt en, rüeft de Zöllner Levi und isst mit Zöllner und Sünder. I Striitgspröch über Vergäbig, Tischgmeinschaft, Faschte und s Äererupfe am Sabbat antwortet er sine Kritiker: De Sabbat isch für de Mänsch da."),
 ("SUM-CH-MRK-004", "Am See lehrt Jesus in Gleichnissen: vom Sämann, von der Lampe, von der selbst wachsenden Saat und vom Senfkorn. Den Jüngern ist das Geheimnis des Reiches Gottes gegeben, doch Jesus fragt sie: «Versteht ihr dieses Gleichnis nicht?» Auf der Überfahrt stillt Jesus den Sturm, und die Jünger fragen: «Wer ist denn dieser?»",
  "Am See leert de Jesus i Gliichnis: vom Sääma, vo de Lampe, vo de Saat, wo vo sälber wachst, und vom Sänfchorn. De Jünger isch s Gheimnis vom Riich vo Gott ggää, aber de Jesus fröget si: «Verstönd er das Gliichnis nöd?» Uf de Überfaart stillt de Jesus de Sturm, und d Jünger fröged: «Wär isch dänn dä?»"),
 ("SUM-CH-MRK-005", "Im Gebiet der Gerasener befreit Jesus einen Mann von einer «Legion» unreiner Geister; der Geheilte verkündet in der Dekapolis, was Jesus an ihm getan hat. Zurück am anderen Ufer heilt er unterwegs zu Jairus eine Frau, die seinen Mantel berührt, und erweckt dann dessen Tochter mit den Worten «Talita kum».",
  "Im Gebiet vo de Gerasener befreit de Jesus en Maa vo ere «Legion» unreine Geischter; de Gheilt verchündet i de Dekapolis, was de Jesus a ihm taa hät. Zrugg am andere Ufer heilt er underwägs zum Jairus e Frau, wo sin Mantel berüert, und weckt dänn dem sini Tochter mit de Wort «Talita kum» uf."),
 ("SUM-CH-MRK-006", "In seiner Heimat stösst Jesus auf Unglauben. Er sendet die Zwölf aus; dazwischen wird erzählt, wie Herodes Johannes den Täufer enthaupten liess. Jesus speist fünftausend Männer mit fünf Broten und zwei Fischen, geht auf dem See zu den Jüngern, deren Herz verhärtet ist, und heilt viele in Gennesaret.",
  "I sinere Heimet stoosst de Jesus uf Unglaube. Er schickt di Zwölf uus; dezwüsche wird verzellt, wie de Herodes de Johannes de Täufer hät loo chöpfe. De Jesus spiist föiftuusig Manne mit föif Broot und zwei Fisch, gaat uf em See zu de Jünger, wo ires Härz verhärtet isch, und heilt vili z Gennesaret."),
 ("SUM-CH-MRK-007", "Mit Pharisäern und Schriftgelehrten streitet Jesus über Händewaschen und Überlieferung: Nicht was von aussen in den Menschen hineingeht, macht ihn unrein, sondern was aus dem Herzen kommt. Im Gebiet von Tyros heilt er die Tochter einer Syrophönizierin, in der Dekapolis einen Tauben mit dem Wort «Effata».",
  "Mit Pharisäer und Schriftgleerte striitet de Jesus über s Händwäsche und d Überliferig: Nöd was vo usse in Mänsch ine gaat, macht en unrein, sondern was us em Härz chunnt. Im Gebiet vo Tyros heilt er d Tochter vo ere Syrophönizierin, i de Dekapolis en Taube mit em Wort «Effata»."),
 ("SUM-CH-MRK-008", "Jesus speist viertausend Menschen, verweigert den Pharisäern ein Zeichen und tadelt die Jünger, die noch nicht verstehen. In Betsaida heilt er einen Blinden in zwei Schritten. Bei Cäsarea Philippi bekennt Petrus: «Du bist der Christus!» Jesus kündigt zum ersten Mal sein Leiden an und ruft zur Nachfolge mit dem Kreuz.",
  "De Jesus spiist viertuusig Mänsche, verwiigeret de Pharisäer es Zeiche und tadlet d Jünger, wo s na nöd verstönd. Z Betsaida heilt er en Blinde i zwei Schritt. Bi Cäsarea Philippi bekännt de Petrus: «Du bisch de Christus!» De Jesus kündet s erscht Mal sis Liide aa und rüeft zur Nachfolg mit em Chrüüz."),
]


def run():
    extra = sorted((p.stem for p in (D / "translations").rglob("TRANS-MRK-00*-WORKING.json")
                    if re.fullmatch(r"TRANS-MRK-00[1-8]-\d{3}-\d{3}-(DE|GSW-ZH)-WORKING", p.stem)
                    and not p.stem.startswith(("TRANS-MRK-003-020", "TRANS-MRK-003-022", "TRANS-MRK-003-031"))),
                   key=lambda x: ("-GSW-" in x, x))
    for sid in ("STUDY-MRK-0002",):
        p = D / "studies" / f"{sid}.json"
        if p.exists() and "Markus 1–8" not in json.loads(p.read_text(encoding="utf-8")).get("title", ""):
            raise SystemExit(f"{sid} existiert schon mit anderem Inhalt; nicht überschreiben")
    _study.write_study({"TAGS": TAGS, "CONTEXT": CONTEXT, "FINDINGS": FINDINGS, "INTERPRETATIONS": INTERPRETATIONS,
                        "PRINCIPLES": PRINCIPLES, "APPLICATIONS": APPLICATIONS, "QUESTIONS": QUESTIONS,
                        "RELATIONS": RELATIONS, "BACKGROUND": BACKGROUND, "SUMMARIES": SUMMARIES,
                        "STUDY": ("STUDY-MRK-0002", "Markus 1–8 (ohne 3,20–35): Studieninhalte", CHAPTERS[1],
                                  extra + [f"SUM-CH-MRK-{c:03d}" for c in (1, 2, 4, 5, 6, 7, 8)],
                                  ["Mundart muttersprachlich prüfen",
                                   "Fachliche Prüfung der Deutungen und des Hintergrunds",
                                   "Sekundärangaben (Targum zu Jes 6,10; Priene-Inschrift; Josephus-Stellen; Masse des Sees, "
                                   "Ginosar-Boot, Entfernungen) an Fachquellen nachprüfen",
                                   "Zählungen beruhen auf MACULA-Lemmata zum SBLGNT; andere Editionen können abweichen"])},
                       "Markus 1–8")


if __name__ == "__main__":
    run()
